import { hex_to_rgb } from '$lib/colors.js';
import { token_value, type Spec } from '$lib/spec.svelte.js';
import { kebabCase } from 'change-case';

export function generate_css(spec: Spec) {
	console.log(spec.tokens);
	let css = `
/* This file was generated by Visual Source; DO NOT EDIT; */

/* COLOR TOKENS */
:root {\n`;
	function append_color_token(name: string, value: string) {
		const rgb = hex_to_rgb(value);
		css += `\t--${name}: ${value};\n`;
		css += `\t--${name}-rgb: ${rgb[0]} ${rgb[1]} ${rgb[2]};\n`;
	}

	for (const t of spec.tokens || []) {
		const value = token_value(t);
		append_color_token(kebabCase(t.name), value);
	}
	css += '}\n\n';

	for (const p of spec.palettes || []) {
		css += `/* PALETTE ${p.name} */\n:root{\n`;
		const prefix = kebabCase(p.name);
		for (const [i, c] of p.colors.entries()) {
			const num = (i + 1).toString().padStart(2, '0');
			append_color_token(`${prefix}-${num}`, c);
		}
		css += '}\n\n';
	}

	if (spec.spacing.scale?.length) {
		css += `/* SPACING */\n:root{\n`;
		for (const t of spec.spacing.scale || []) {
			const value = token_value(t);
			css += `\t--${kebabCase(t.name)}: ${value};\n`;
		}
		css += '}\n\n';
	}
	return css.trim();
}
